function backlogSize(orders: number[][]): number {
  const buys: number[][] = [], sells: number[][] = [];
  for (const [price, amount, type] of orders) {
    let left = amount;
    const other = type === 0 ? sells : buys;
    while (left > 0) {
      let best = -1;
      for (let i = 0; i < other.length; i++) {
        const ok = type === 0 ? other[i][0] <= price : other[i][0] >= price;
        if (!ok) continue;
        if (best < 0 || (type === 0 ? other[i][0] < other[best][0] : other[i][0] > other[best][0])) best = i;
      }
      if (best < 0) break;
      const take = Math.min(left, other[best][1]);
      left -= take;
      other[best][1] -= take;
      if (other[best][1] === 0) other.splice(best, 1);
    }
    if (left > 0) (type === 0 ? buys : sells).push([price, left]);
  }
  let total = 0;
  for (const [, a] of buys) total += a;
  for (const [, a] of sells) total += a;
  return total % 1000000007;
}

