class Solution:
    def backlogSize(self, orders: List[List[int]]) -> int:
        buys, sells = [], []
        for price, amount, typ in orders:
            left = amount
            other = sells if typ == 0 else buys
            while left > 0:
                if typ == 0:
                    cands = [i for i in range(len(other)) if other[i][0] <= price]
                    best = min(cands, key=lambda i: other[i][0]) if cands else -1
                else:
                    cands = [i for i in range(len(other)) if other[i][0] >= price]
                    best = max(cands, key=lambda i: other[i][0]) if cands else -1
                if best < 0:
                    break
                take = min(left, other[best][1])
                left -= take
                other[best][1] -= take
                if other[best][1] == 0:
                    other.pop(best)
            if left > 0:
                (buys if typ == 0 else sells).append([price, left])
        return (sum(a for _, a in buys) + sum(a for _, a in sells)) % 1_000_000_007

