class Heap {
  a: number[][] = [];
  constructor(private before: (x: number[], y: number[]) => boolean) {}
  get size() { return this.a.length; }
  top(): number[] { return this.a[0]; }
  push(x: number[]): void {
    const a = this.a; a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!this.before(a[i], a[p])) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  pop(): number[] {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && this.before(a[l], a[m])) m = l;
        if (r < a.length && this.before(a[r], a[m])) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

function backlogSize(orders: number[][]): number {
  const sells = new Heap((x, y) => x[0] < y[0]); // cheapest first
  const buys = new Heap((x, y) => x[0] > y[0]);  // highest first
  for (const [price, amount, type] of orders) {
    let left = amount;
    const other = type === 0 ? sells : buys;
    const crosses = (p: number) => (type === 0 ? p <= price : p >= price);
    while (left > 0 && other.size > 0 && crosses(other.top()[0])) {
      const top = other.top();
      const take = Math.min(left, top[1]);
      left -= take;
      top[1] -= take;
      if (top[1] === 0) other.pop();
    }
    if (left > 0) (type === 0 ? buys : sells).push([price, left]);
  }
  let total = 0;
  for (const [, a] of buys.a) total += a;
  for (const [, a] of sells.a) total += a;
  return total % 1000000007;
}

